import { lazy, type ComponentType, type LazyExoticComponent } from "react";

type SurfaceModule = { Route: { options: { component?: ComponentType } } };

function leaf(loader: () => Promise<SurfaceModule>): LazyExoticComponent<ComponentType> {
  return lazy(async () => {
    const mod = await loader();
    const Comp = mod.Route.options.component;
    if (!Comp) throw new Error("bound scholar surface is missing a component");
    return { default: Comp };
  });
}

